/* =====================================================================
   Store items - OLD data copy: TOP 100 MOST USED items  —  2026-11-13
   Source : OLD HIS DEMO_HIS_NEW (exported 2026-11-13; the data is inside this script, the OLD DB is not needed)
   Target : GWT_HIS_API.dbo.ServiceItemMaster
   Run AFTER: Manufacturer, Salt, GST Slab, Drug Category, Rack master scripts,
              2026-11-13_StoreItemMaster_Lookups.sql and 2026-11-13_StoreItemMaster.sql
   Re-runnable: yes - inserts only items / groups whose id is not present yet. All-or-nothing (one transaction).

   "Most used" = number of non-cancelled OLD sale / issue lines (FinancialTransactions.TnxType OPDSell, IPDIssue,
   DeparmentIssue -> FinancialTransactionDetails), ties broken by total quantity. 502 OLD store items have such lines;
   this script copies the first 100 (Lines 196 ... 8; all 100 are Medical, all active).

   Rules applied
     * OLD ServiceItemId kept (IDENTITY_INSERT; no collision with NEW ids), so OLD stock / sales can be linked later.
       Manufacturer, Salt (DescriptionId), Drug Category, Purchase / Sale Unit, GST, Doctor ids are the OLD ids,
       which the earlier master copies kept unchanged.
     * Sub-sub groups SURGICAL (36394) and TABLAT (36399) under MEDICINE (20860) do not exist in NEW -> copied with OLD ids.
     * 7 OLD items point to groups that cannot hold a Medical item (lab groups BIOCHEMISTRY 10 / MICROBIOLOGY 13 of
       sub group 1, and General-store group Cath Lab 29252) -> placed in Medical groups (Recommended, owner to confirm):
         lab reagents / susceptibility discs -> CONSUMABLE (20861) > CONSUMABLE   (29259)
         Amplatzer cath-lab devices        -> CONSUMABLE (20861) > SURGICAL CTVS (29269)
     * Dosage Form (design field, not in OLD) derived from the OLD sub-sub group name where it is unambiguous:
         INJ / INJECTION -> Injection, TABLET / TABLETS / TABLAT -> Tablet, CAPSULES / CAPULES / ROTACAPS -> Capsule,
         SYRUP -> Syrup, *DROPS -> Drops, OINTMENT / CREAM -> Ointment / Cream; otherwise left empty.
     * Salt text without a salt id (OLD saved the placeholder "--Select--") -> NULL.
     * Empty item code -> NULL. GST value that is not a NEW GST slab -> NULL (none of the 100 has a bad value; 2 have none).
     * Pack Size, Strength, Barcode, Drug Schedule, Rack, Cold Chain are design fields that OLD never had -> empty.
   Items that are now Medical but incomplete (no salt / dosage form / pack size / HSN / GST) stay valid; the
   Store Item Master asks for the missing fields when such an item is next edited (owner decision 2026-11-13).
   The last result set lists them.
   ===================================================================== */

SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

/* ---------- groups needed by the 100 items ---------- */
IF NOT EXISTS (SELECT 1 FROM dbo.SubCategoryMaster WHERE SubCategoryId = 20860 AND CategoryId = 6)
   OR NOT EXISTS (SELECT 1 FROM dbo.SubSubCategoryMaster WHERE SubSubCategoryId = 29259 AND SubCategoryId = 20861)
   OR NOT EXISTS (SELECT 1 FROM dbo.SubSubCategoryMaster WHERE SubSubCategoryId = 29269 AND SubCategoryId = 20861)
   OR NOT EXISTS (SELECT 1 FROM dbo.SubCategoryMaster WHERE SubCategoryId = 20861 AND CategoryId = 6)
BEGIN
    RAISERROR('Required Medical groups MEDICINE (20860) / CONSUMABLE (20861) > CONSUMABLE (29259), SURGICAL CTVS (29269) not found. Nothing was copied.', 16, 1);
    ROLLBACK;
    RETURN;
END

SET IDENTITY_INSERT dbo.SubSubCategoryMaster ON;
INSERT INTO dbo.SubSubCategoryMaster (HospId, SubSubCategoryId, SubSubCategoryName, SubCategoryId, Alias, PrintOrder, IsActive, CreatedBy, CreatedOn, IpAddress, UniqueId)
SELECT s.HospId, s.Id, s.Name, s.SubCategoryId, s.Alias, s.PrintOrder, s.IsActive, s.CreatedBy, s.CreatedOn, s.IpAddress, s.UniqueId
FROM (VALUES
    (1,36394,N'SURGICAL',20860,N'SURGICAL',NULL,1,1,'2026-02-07 17:05:46.010',NULL,N'A6A5DEFE-D51C-4692-84C4-BB9DE99B40D5'),
    (1,36399,N'TABLAT',20860,N'TABLAT',NULL,1,1,'2026-02-07 17:05:46.010',NULL,N'8FC10128-CAA1-4E43-8647-CFD7570FE6B5')
     ) s (HospId, Id, Name, SubCategoryId, Alias, PrintOrder, IsActive, CreatedBy, CreatedOn, IpAddress, UniqueId)
WHERE NOT EXISTS (SELECT 1 FROM dbo.SubSubCategoryMaster t WHERE t.SubSubCategoryId = s.Id);
SET IDENTITY_INSERT dbo.SubSubCategoryMaster OFF;

/* ---------- the 100 OLD items ---------- */
IF OBJECT_ID('tempdb..#item') IS NOT NULL DROP TABLE #item;
CREATE TABLE #item
(
    Rnk int, UsageLines int,
    ServiceItemId int, HospId int, CategoryId int, SubCategoryId int, SubSubCategoryId int, OldSubSubName nvarchar(256),
    Name nvarchar(2048), Code nvarchar(100), IsActive int,
    CreatedBy int, CreatedOn datetime, LastModifiedBy int, LastModifiedOn datetime, IpAddress nvarchar(40), UniqueId nvarchar(100),
    DescriptionId int, ItemDiscription nvarchar(512), HSNCode nvarchar(40), CommodityCode nvarchar(40),
    ManufacturerId int, DrugCategoryId int, VEDType nvarchar(100), Expirable int,
    PurchaseUnitId int, SaleUnitId int, Packing int, GSTPer decimal(36,6), DoctorId int,
    MinLevel nvarchar(100), MaxLevel nvarchar(100), ReorderLevel nvarchar(100), StockType int,
    IsBagTypeItem int, IsBagTypeId int, IsKitTypeItem int, CorporateIds nvarchar(max),
    StatusId int, StatusType nvarchar(100), MedicineHoldRemorks nvarchar(max), HoldDepartmentId int
);

