-- groups that cannot hold a Medical item -> closest Medical groups (see header)
UPDATE #item SET SubCategoryId = 20861, SubSubCategoryId = 29259 WHERE SubSubCategoryId IN (10, 13);
UPDATE #item SET SubCategoryId = 20861, SubSubCategoryId = 29269 WHERE SubSubCategoryId = 29252;

-- any other hierarchy mismatch would be a new case: stop rather than guess
IF EXISTS (SELECT 1 FROM #item i
           WHERE NOT EXISTS (SELECT 1 FROM dbo.SubCategoryMaster s WHERE s.SubCategoryId = i.SubCategoryId AND s.CategoryId = i.CategoryId)
              OR NOT EXISTS (SELECT 1 FROM dbo.SubSubCategoryMaster s WHERE s.SubSubCategoryId = i.SubSubCategoryId AND s.SubCategoryId = i.SubCategoryId))
BEGIN
    SELECT i.ServiceItemId, i.Name, i.CategoryId, i.SubCategoryId, i.SubSubCategoryId FROM #item i
    WHERE NOT EXISTS (SELECT 1 FROM dbo.SubCategoryMaster s WHERE s.SubCategoryId = i.SubCategoryId AND s.CategoryId = i.CategoryId)
       OR NOT EXISTS (SELECT 1 FROM dbo.SubSubCategoryMaster s WHERE s.SubSubCategoryId = i.SubSubCategoryId AND s.SubCategoryId = i.SubCategoryId);
    RAISERROR('Some items have groups that do not exist in this database (listed above). Nothing was copied.', 16, 1);
    ROLLBACK;
    RETURN;
END

SET IDENTITY_INSERT dbo.ServiceItemMaster ON;
INSERT INTO dbo.ServiceItemMaster
(
    ServiceItemId, HospId, CategoryId, SubCategoryId, SubSubCategoryId, Name, Code, IsActive,
    CreatedBy, CreatedOn, LastModifiedBy, LastModifiedOn, IpAddress, UniqueId,
    DescriptionId, ItemDiscription, HSNCode, CommodityCode, ManufacturerId, DrugCategoryId, VEDType, Expirable,
    PurchaseUnitId, PurchaseUnitName, SaleUnitId, SaleUnitName, Packing, GSTPer, DoctorId,
    MinLevel, MaxLevel, ReorderLevel, StockType, IsBagTypeItem, IsBagTypeId, IsKitTypeItem, CorporateIds,
    StatusId, StatusType, MedicineHoldRemorks, HoldDepartmentId,
    DosageFormId, IsColdChain
)
SELECT
    i.ServiceItemId, i.HospId, i.CategoryId, i.SubCategoryId, i.SubSubCategoryId, LTRIM(RTRIM(i.Name)), NULLIF(LTRIM(RTRIM(i.Code)), ''), i.IsActive,
    i.CreatedBy, i.CreatedOn, i.LastModifiedBy, i.LastModifiedOn, i.IpAddress, i.UniqueId,
    -- OLD stored the dropdown placeholder "--Select--" as salt text when no salt was chosen
    NULLIF(i.DescriptionId, 0),
    CASE WHEN NULLIF(i.DescriptionId, 0) IS NULL THEN NULL ELSE NULLIF(i.ItemDiscription, '') END,
    NULLIF(i.HSNCode, ''), NULLIF(i.CommodityCode, ''),
    i.ManufacturerId, NULLIF(i.DrugCategoryId, 0), i.VEDType, i.Expirable,
    i.PurchaseUnitId, pu.PurchaseUnitName, i.SaleUnitId, su.SaleUnitName, i.Packing,
    CASE WHEN EXISTS (SELECT 1 FROM dbo.TaxPercentage tp WHERE tp.TaxValue = i.GSTPer) THEN i.GSTPer END,
    NULLIF(i.DoctorId, 0),
    i.MinLevel, i.MaxLevel, i.ReorderLevel, i.StockType, ISNULL(i.IsBagTypeItem, 0), ISNULL(i.IsBagTypeId, 0), ISNULL(i.IsKitTypeItem, 0), i.CorporateIds,
    i.StatusId, i.StatusType, i.MedicineHoldRemorks, i.HoldDepartmentId,
    (SELECT TOP 1 df.DosageFormId FROM dbo.DosageFormMaster df WHERE df.DosageFormName =
        CASE
            WHEN i.OldSubSubName IN (N'INJ', N'INJECTION', N'INJECTION-FRIDGE')        THEN N'Injection'
            WHEN i.OldSubSubName IN (N'TABLET', N'TABLETS', N'TABLAT')                 THEN N'Tablet'
            WHEN i.OldSubSubName IN (N'CAPSULES', N'CAPULES', N'ROTACAPS')             THEN N'Capsule'
            WHEN i.OldSubSubName = N'SYRUP'                                            THEN N'Syrup'
            WHEN i.OldSubSubName LIKE N'%DROPS'                                        THEN N'Drops'
            WHEN i.OldSubSubName IN (N'OINTMENT', N'CREAM')                            THEN N'Ointment / Cream'
        END),
    0
FROM #item i
LEFT JOIN dbo.PurchaseUnitMaster pu ON pu.PurchaseUnitId = i.PurchaseUnitId
LEFT JOIN dbo.SaleUnitMaster su     ON su.SaleUnitId = i.SaleUnitId
WHERE NOT EXISTS (SELECT 1 FROM dbo.ServiceItemMaster t WHERE t.ServiceItemId = i.ServiceItemId);
PRINT CAST(@@ROWCOUNT AS varchar) + ' store item(s) copied.';
SET IDENTITY_INSERT dbo.ServiceItemMaster OFF;

COMMIT;

/* ---------- report ---------- */
-- items moved to another group
SELECT i.Rnk, i.ServiceItemId, i.Name, i.OldSubSubName AS OldGroup, ssc.SubSubCategoryName AS NewGroup
FROM #item i JOIN dbo.SubSubCategoryMaster ssc ON ssc.SubSubCategoryId = i.SubSubCategoryId
WHERE i.OldSubSubName IN (N'BIOCHEMISTRY', N'MICROBIOLOGY', N'Cath Lab')
ORDER BY i.Rnk;

-- Medical items that will need completing on next edit
SELECT i.Rnk, sim.ServiceItemId, sim.Name,
       CASE WHEN sim.DescriptionId IS NULL THEN 'Salt ' ELSE '' END +
       CASE WHEN sim.DosageFormId  IS NULL THEN 'DosageForm ' ELSE '' END +
       CASE WHEN sim.PackSize      IS NULL THEN 'PackSize ' ELSE '' END +
       CASE WHEN sim.HSNCode       IS NULL THEN 'HSN ' ELSE '' END +
       CASE WHEN sim.GSTPer        IS NULL THEN 'GST ' ELSE '' END +
       CASE WHEN sim.PurchaseUnitId IS NULL THEN 'PurchaseUnit ' ELSE '' END AS Missing
FROM #item i JOIN dbo.ServiceItemMaster sim ON sim.ServiceItemId = i.ServiceItemId
WHERE sim.CategoryId = 6
  AND (sim.DescriptionId IS NULL OR sim.DosageFormId IS NULL OR sim.PackSize IS NULL OR sim.HSNCode IS NULL OR sim.GSTPer IS NULL OR sim.PurchaseUnitId IS NULL)
ORDER BY i.Rnk;

DROP TABLE #item;
GO
